-- Adds the payments:request permission to the built-in roles. System roles are immutable, so the guard trigger is dropped for this migration and recreated.
DROP TRIGGER roles_system_no_update;
UPDATE roles SET permissions = '["conversations:read","conversations:reply","conversations:assign","conversations:delete","contacts:read","contacts:write","contacts:import","contacts:delete","inboxes:manage","members:read","members:manage","roles:manage","settings:read","settings:write","channels:manage","tokens:manage","templates:manage","kb:manage","ai:use","billing:manage","payments:request","analytics:read","analytics:export","analytics_identity:manage","api_keys:manage","audit:read"]' WHERE id = 'role_owner';
UPDATE roles SET permissions = '["conversations:read","conversations:reply","conversations:assign","conversations:delete","contacts:read","contacts:write","contacts:import","contacts:delete","inboxes:manage","members:read","members:manage","settings:read","settings:write","channels:manage","tokens:manage","templates:manage","kb:manage","ai:use","payments:request","analytics:read","analytics:export","api_keys:manage","audit:read"]' WHERE id = 'role_manager';
UPDATE roles SET permissions = '["conversations:read","conversations:reply","contacts:read","contacts:write","members:read","settings:read","ai:use","payments:request"]' WHERE id = 'role_agent';
UPDATE roles SET permissions = '["conversations:read","contacts:read","members:read","settings:read","analytics:read"]' WHERE id = 'role_viewer';
CREATE TRIGGER roles_system_no_update BEFORE UPDATE ON roles WHEN OLD.is_system = 1 BEGIN SELECT RAISE(ABORT, 'system roles are immutable'); END;
